def get(self, key, default=None):
    """Return the value associated with `key`, converted from its stored snapshot representation. If `key` is not present, return `default`."""
    try:
        return from_snapshot(self._lookup(key))
    except KeyError:
        return default

def __call__(self, *args, **kwargs):
    """Invokes the wrapped callable with unwrapped positional and keyword arguments. Returns the finalized result, preserving asynchronous behavior when the wrapped callable returns a coroutine."""
    # Unwrap arguments
    unwrapped_args = [unwrap(arg) for arg in args]
    unwrapped_kwargs = {k: unwrap(v) for k, v in kwargs.items()}

    # Call the real function with unwrapped arguments
    result = self._td_real(*unwrapped_args, **unwrapped_kwargs)

    # Handle asynchronous result
    if inspect.isawaitable(result):
        return self._finish_async(result, unwrapped_args, unwrapped_kwargs)

    # Finish recording for synchronous result
    return self._finish(result, unwrapped_args, unwrapped_kwargs, is_async=False)

def __getattr__(self, name):
    """Resolves an attribute name within the recorded tape at the current path. Returns a callable, nested tape object, or snapshot value for the name, or raises `ResolutionError` if no recorded value exists."""
    result_path = f"{self._path}.{name}"

    if self._player._has_prefix(result_path):
        # If the result_path is a valid container, return a new TapeObject
        return TapeObject(self._player, result_path)

    # Try to get the snapshot value if it's not a callable/container
    try:
        value = from_snapshot(self._player.tape["mocked_modules"][self._path]["methods"][name])
        return value
    except (KeyError, TypeError):
        raise ResolutionError(f"{self._path} has no attribute {name!r}") from None

def __getattr__(self, name):
    """Resolves an attribute name within the recorded tape at the current path. Returns a callable, nested tape object, or snapshot value for the name, or raises `ResolutionError` if no recorded value exists."""
    result_path = f"{self._path}.{name}"

    if self._player._has_prefix(result_path):
        # If the result_path is a valid container, return a new TapeObject
        return TapeObject(self._player, result_path)

    methods = self._player.containers.get(self._path, {}).get("methods", {})

    if name in methods:
        return TapeCallable(self._player, self._path, name, methods[name])

    # If it's not found, check for snapshot value
    try:
        value = from_snapshot(self._player.tape["mocked_modules"][self._path]["methods"][name])
        return value
    except (KeyError, TypeError):
        raise ResolutionError(f"{self._path} has no attribute {name!r}") from None

def diff_transcript(recorded_out: List[dict], transcript: List[dict], client_path: str) -> List[str]:
    """Pure comparison: replayed calls must match the recorded ones in order."""
    drift: List[str] = []

    if len(recorded_out) != len(transcript):
        drift.append(f"recorded and transcript lengths differ: {len(recorded_out)} vs {len(transcript)}")

    for i, (recorded, replayed) in enumerate(zip(recorded_out, transcript)):
        if recorded['event'] != replayed['event']:
            drift.append(f"difference at index {i}: recorded event {recorded['event']} vs replayed event {replayed['event']}")
        if recorded.get('args', None) != replayed.get('args', None):
            drift.append(f"difference at index {i}: recorded args {recorded.get('args', None)} vs replayed args {replayed.get('args', None)}")
        if recorded.get('kwargs', None) != replayed.get('kwargs', None):
            drift.append(f"difference at index {i}: recorded kwargs {recorded.get('kwargs', None)} vs replayed kwargs {replayed.get('kwargs', None)}")

    return drift

def diff_transcript(recorded_out: List[dict], transcript: List[dict], client_path: str) -> List[str]:
    """Pure comparison: replayed calls must match the recorded ones in order."""
    drift: List[str] = []

    if len(recorded_out) != len(transcript):
        drift.append(f"recorded and transcript lengths differ: {len(recorded_out)} vs {len(transcript)}")

    for i in range(max(len(recorded_out), len(transcript))):
        recorded = recorded_out[i] if i < len(recorded_out) else None
        replayed = transcript[i] if i < len(transcript) else None

        if recorded is None:
            drift.append(f"extra transcript at index {i}: {replayed}")
            continue
        if replayed is None:
            drift.append(f"missing transcript at index {i}: {recorded}")
            continue

        for key in ['event', 'args', 'kwargs']:
            if recorded.get(key) != replayed.get(key):
                drift.append(f"difference at index {i}: recorded {key} {recorded.get(key)} vs replayed {key} {replayed.get(key)}")

    return drift

def __getattr__(self, name):
    """Delegates attribute access to the wrapped module, returning private attributes unchanged.
    Wraps public classes and callables in proxy objects while returning other values directly."""
    value = getattr(self._td_real, name)
    if name.startswith("_"):
        return value
    if callable(value) and not inspect.isclass(value):
        return CallableWrapper(value, self._rec, self._red, self._td_real.__name__, name)
    if _should_wrap_result(value):
        return ObjectProxy(value, self._rec, self._red, name)
    return value

