def render_json(report) -> dict:
    """Lines with their status, findings, and the evidence per test: which tests ran each
    changed line, which noticed its mutant, and what each of those tests fakes. Tools that
    know what a test is *for* (specdeck's requirements) join on the node ids."""
    from collections import defaultdict

    lines_data = []
    for (path, line), status in report.lines.items():
        line_info = {
            "line": line,
            "status": status.name.lower(),
            "ran_by": [],
            "killed_by": []
        }
        # Collecting which tests ran the line and which tests noticed the mutant
        for finding in report.findings:
            if finding.path == path and finding.line == line:
                if finding.ran_by:
                    line_info['ran_by'].extend(finding.ran_by)
                if finding.killed_by:
                    line_info['killed_by'].extend(finding.killed_by)

        lines_data.append(line_info)

    tests_data = []
    tests_seen = set()
    for finding in report.findings:
        for test in finding.tests:
            if test.nodeid not in tests_seen:
                tests_seen.add(test.nodeid)
                tests_data.append({
                    "nodeid": test.nodeid,
                    "fakes": test.fakes
                })

    return {
        "lines": lines_data,
        "tests": tests_data,
        "findings": report.findings,
        "reach": report.reach,
    }

