def is_arid(source: str, line: int) -> bool:
    """True when `line` of `source` should never be mutated."""
    import ast

    tree = ast.parse(source)
    line_node = next((node for node in ast.walk(tree) if hasattr(node, 'lineno') and node.lineno == line), None)

    if line_node is None:
        return False

    # Check for logging, print, sleep, imports, docstrings, main guards, and type-only lines
    if isinstance(line_node, (ast.Expr, ast.Import, ast.ImportFrom)):
        return True
    if isinstance(line_node, ast.FunctionDef):
        if is_docstring(line_node):
            return True
        if _in_main_guard(line_node, {n: p for p in ast.walk(tree) for n in ast.walk(p) if isinstance(n, ast.AST)}):
            return True
    if isinstance(line_node, ast.Assign) and all(isinstance(target, ast.Name) and target.id in {"value"} for target in line_node.targets):
        return False

    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and node.lineno == line:
            if _is_noise_call(node):
                return True

    return False

def vacuous_assertions(test_source: str, path: str = "<test>") -> list:
    """Returns findings for assertions in the given test source that appear vacuous, such as always-true checks or assertions that only verify type or non-None status. The optional path is included in each finding, and invalid source returns an empty list."""
    test_tree = _parse(test_source)
    if test_tree is None:
        return []

    found = []
    for node in ast.walk(test_tree):
        if isinstance(node, ast.Assert):
            # Check for assertions that are always True
            if isinstance(node.test, ast.Constant) and node.test.value is True:
                found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS))
            # Check for assertions that check if a value is None
            elif isinstance(node.test, ast.UnaryOp) and isinstance(node.test.op, ast.Not) and isinstance(node.test.operand, ast.Name) and node.test.operand.id == 'None':
                found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS))
            # Check for isinstance assertions
            elif isinstance(node.test, ast.Call) and isinstance(node.test.func, ast.Name) and node.test.func.id == 'isinstance':
                found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS))

    return found

def exit_code(report, gate: bool = True) -> int:
    """1 when gating and something is unverified: a surviving mutant, a changed line no test runs,
    a weakened test or a checker change. Unconfirmed expectations and the other detectors are
    advisory and never fail the gate on their own."""

    if not gate:
        return 0

    if any(f.kind in GATING for f in report.findings):
        return 1

    return 0

def select(candidates: dict, cap_per_file: int = 7) -> list:
    """At most one mutant per line (its first, most useful candidate), at most `cap_per_file` per file.

    `candidates`: {path: {line: [Mutant, ...]}}. Lines are taken top to bottom.
    """
    selected = []
    counts = {}

    for path, lines in candidates.items():
        if path not in counts:
            counts[path] = 0

        for line, mutants in sorted(lines.items()):
            if counts[path] >= cap_per_file:
                break
            if mutants:  # Check if there are any mutants for this line
                selected.append(mutants[0])  # Select the first candidate
                counts[path] += 1

    return selected

def exit_code(model: dict, *, fail_on_failing=False, fail_on_unmet=False, fail_on_untrusted=False) -> int:
    """Return an exit status for a results model, optionally treating failing checks, unmet requirements, or untrusted items as errors. Returns 1 when an enabled failure condition is present, otherwise 0."""
    exit_status = 0

    if fail_on_failing and model["counts"].get("failed", 0) > 0:
        exit_status = 1

    if fail_on_unmet and model.get("requirements") and model["requirements"]["counts"].get("failing", 0) > 0:
        exit_status = 1

    if fail_on_untrusted and model.get("trust") and any(item["status"] != "met" for item in model["trust"]["requirements"]):
        exit_status = 1

    return exit_status

def stop(self) -> dict:
    """``{nodeid: {(abs path, line)}}``, import-time lines removed."""
    if self._cov is None:
        return {}
    self._cov.stop()
    self._cov.switch_context(IMPORT_CONTEXT)
    data = self._cov.get_data()
    result: dict = {}

    for nodeid in data.measured.keys():
        result[nodeid] = set()
        lines = data.measured[nodeid]
        for filename in lines:
            for line in lines[filename]:
                result[nodeid].add((filename, line))

    # Remove import-time lines
    for nodeid in list(result.keys()):
        result[nodeid] = {item for item in result[nodeid] if item[0] not in self.sources}

    return {nodeid: tuple(sorted(result[nodeid])) for nodeid in result}

def validate_requirements_file(path) -> list:
    """Diagnostics for a hand-written requirements file.

    ``requirements.load`` already collects its own problems rather than raising;
    this turns them into the same Diagnostic shape so one command reports both.
    """
    from pathlib import Path
    import yaml

    p = Path(path)
    if not p.exists():
        return [Diagnostic("error", "NO_FILE", f"{p} does not exist.")]

    try:
        text = p.read_text(encoding="utf-8")
        data = yaml.safe_load(text)
    except OSError as e:
        return [Diagnostic("error", "UNREADABLE", f"Cannot read {p}: {e}")]
    except yaml.YAMLError as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE", f"{p} is not valid YAML: {e}")]

    if not isinstance(data, dict) or "requirements" not in data:
        return [Diagnostic("error", "NO_REQUIREMENTS", f"{p} must contain a `requirements` key.")]

    diags = []
    seen_ids = set()

    for i, req in enumerate(data["requirements"]):
        path = f"requirements[{i}]"
        if not isinstance(req, dict):
            diags.append(Diagnostic("error", "BAD_REQUIREMENT", f"Requirement must be a mapping, found {type(req).__name__}.", path=path))
            continue

        req_id = str(req.get("id") or "")
        if not req_id:
            diags.append(Diagnostic("error", "NO_ID", "Requirement has no `id`.", path=path))
        elif req_id in seen_ids:
            diags.append(Diagnostic("error", "DUP_ID", f"Duplicate requirement id `{req_id}`.", path=path))
        else:
            seen_ids.add(req_id)

        for key in req:
            if key != "id" and key != "says":
                diags.append(Diagnostic("warning", "UNKNOWN_KEY", f"Unknown requirement key `{key}`.", path=path))

    return diags

