def snapshot(root: Path) -> dict:
    """path -> signature for every watched file under root."""
    from pathlib import Path
    result = {}

    for path in root.rglob('*'):
        if path.is_file() and path.suffix in WATCH_SUFFIXES:
            if not any(dir in path.parts for dir in IGNORE_DIRS):
                result[str(path)] = _signature(path)

    return result
